def forward(self, inputs, cond_inputs=None, mode='direct'):
    if mode == 'direct':
        s = torch.sigmoid
        return s(inputs), torch.log(s(inputs) * (1 - s(inputs))).sum(
            -1, keepdim=True)
    else:
        return torch.log(inputs /
                         (1 - inputs)), -torch.log(inputs - inputs**2).sum(
                             -1, keepdim=True)

